${pagingTop} SELECT HOMEPAGE_ID, RESERVE_STATUS, DEVICE_IDX, DEVICE_CODE, RESERVE_IDX, RESERVE_BUNDLE_IDX, LOCKER_IDX, DEVICE_PASSWORD, DEVICE_NAME, MEMBER_ID, USER_KEY, MEMBER_NAME, LEND_DATE, MANAGE_CODE, LIB_NAME, BOOK_KEY, REG_NO, BOOK_ISBN, BOOK_NAME, ADD_DATE, ADD_ID, ADD_IP, CANCEL_YN, CANCEL_DATE, CANCEL_REASON, CANCEL_ID, CANCEL_IP, SMS_SEND_YN, SMS_SEND_DATE, HOMEPAGE_SEND_TELL, APPLICANT_CELL_PHONE, EXPIRE_DATE_CNT, PK, LARGE_BOOK_YN, USER_NO, TAKE_TERM, RESERVE_END_DATE, RESERVE_START_DATE, RETURN_DEVICE_CODE, EXPIRE_DATE, CALL_NO FROM NEIGHBORHOOD_LIBRARY_RESERVE WHERE 1=1
AND DEVICE_IDX = #{device_idx}
AND (RESERVE_STATUS = '3' AND TO_CHAR(EXPIRE_DATE, 'yyyy-MM-dd') < TO_CHAR(SYSDATE, 'yyyy-MM-dd'))
AND RESERVE_STATUS = #{reserve_status}
AND HOMEPAGE_ID = #{homepage_id}
AND manage_code = #{manage_code}
AND TO_DATE(add_date,'yyyy-MM-dd') BETWEEN #{start_date} AND #{end_date}
AND ${search_type} LIKE '%'||#{search_text}||'%'
AND add_date BETWEEN TO_DATE(TO_CHAR(SYSDATE, 'yyyy-MM-dd') || ' 09', 'yyyy-MM-dd HH24') AND TO_DATE(TO_CHAR(SYSDATE + 1, 'yyyy-MM-dd') || ' 09', 'yyyy-MM-dd HH24')
ORDER BY ADD_DATE DESC, RESERVE_BUNDLE_IDX ${pagingBottom}

SELECT COUNT(*) FROM NEIGHBORHOOD_LIBRARY_RESERVE WHERE 1=1
AND DEVICE_IDX = #{device_idx}
AND (RESERVE_STATUS = '3' AND TO_CHAR(EXPIRE_DATE, 'yyyy-MM-dd') < TO_CHAR(SYSDATE, 'yyyy-MM-dd'))
AND RESERVE_STATUS = #{reserve_status}
AND HOMEPAGE_ID = #{homepage_id}
AND manage_code = #{manage_code}
AND TO_DATE(add_date,'yyyy-MM-dd') BETWEEN #{start_date} AND #{end_date}
AND ${search_type} LIKE '%'||#{search_text}||'%'
AND RESERVE_STATUS IN ('1','2')
AND add_date BETWEEN TO_DATE(TO_CHAR(SYSDATE -1, 'yyyy-MM-dd') || ' 09', 'yyyy-MM-dd HH24') AND TO_DATE(TO_CHAR(SYSDATE, 'yyyy-MM-dd') || ' 09', 'yyyy-MM-dd HH24')
AND RESERVE_STATUS IN ('6','7') AND (RESERVE_STATUS = '3' AND TO_CHAR(EXPIRE_DATE, 'yyyy-MM-dd') < TO_CHAR(SYSDATE, 'yyyy-MM-dd'))
AND manage_code = #{manage_code}
AND add_date BETWEEN TO_DATE(TO_CHAR(SYSDATE, 'yyyy-MM-dd') || ' 09', 'yyyy-MM-dd HH24') AND TO_DATE(TO_CHAR(SYSDATE + 1, 'yyyy-MM-dd') || ' 09', 'yyyy-MM-dd HH24')
ORDER BY ADD_DATE DESC, RESERVE_BUNDLE_IDX

SELECT HOMEPAGE_ID, RESERVE_STATUS, DEVICE_IDX, DEVICE_CODE, RESERVE_IDX, RESERVE_BUNDLE_IDX, LOCKER_IDX, DEVICE_PASSWORD, DEVICE_NAME, MEMBER_ID, USER_KEY, MEMBER_NAME, LEND_DATE, MANAGE_CODE, LIB_NAME, BOOK_KEY, REG_NO, BOOK_ISBN, BOOK_NAME, ADD_DATE, ADD_ID, ADD_IP, CANCEL_YN, CANCEL_DATE, CANCEL_REASON, CANCEL_ID, CANCEL_IP, SMS_SEND_YN, SMS_SEND_DATE, HOMEPAGE_SEND_TELL, APPLICANT_CELL_PHONE, EXPIRE_DATE_CNT, PK, LARGE_BOOK_YN, USER_NO, TAKE_TERM, RESERVE_END_DATE, RESERVE_START_DATE, RETURN_DEVICE_CODE, EXPIRE_DATE, CALL_NO FROM NEIGHBORHOOD_LIBRARY_RESERVE WHERE 1=1 AND RESERVE_IDX = #{reserve_idx}
AND RESERVE_STATUS = '1'
AND RESERVE_STATUS = #{reserve_status} AND DEVICE_CODE = #{device_code}
AND RESERVE_STATUS in ('1','2')

SELECT HOMEPAGE_ID, RESERVE_STATUS, DEVICE_IDX, DEVICE_CODE, RESERVE_IDX, RESERVE_BUNDLE_IDX, LOCKER_IDX, DEVICE_PASSWORD, DEVICE_NAME, MEMBER_ID, USER_KEY, MEMBER_NAME, LEND_DATE, MANAGE_CODE, LIB_NAME, BOOK_KEY, REG_NO, BOOK_ISBN, BOOK_NAME, ADD_DATE, ADD_ID, ADD_IP, CANCEL_YN, CANCEL_DATE, CANCEL_REASON, CANCEL_ID, CANCEL_IP, SMS_SEND_YN, SMS_SEND_DATE, HOMEPAGE_SEND_TELL, APPLICANT_CELL_PHONE, EXPIRE_DATE_CNT, PK, LARGE_BOOK_YN, USER_NO, TAKE_TERM, RESERVE_END_DATE, RESERVE_START_DATE, RETURN_DEVICE_CODE, EXPIRE_DATE, CALL_NO FROM NEIGHBORHOOD_LIBRARY_RESERVE WHERE 1=1 AND RESERVE_IDX = #{reserve_idx}
AND LOCKER_IDX = #{locker_idx}
AND RESERVE_STATUS = #{reserve_status}

mapper.update:
UPDATE 
	NEIGHBORHOOD_LIBRARY_RESERVE
SET
	RESERVE_STATUS = #{reserve_status}

	,LEND_DATE = SYSDATE
	,TAKE_TERM = #{take_term}
	,EXPIRE_DATE_CNT = #{expire_date_cnt}
	,MOD_ID = #{mod_id}
	,MOD_IP = #{mod_ip}
	,MOD_DATE = SYSDATE	

		, LOCKER_IDX = #{locker_idx}


		, DEVICE_PASSWORD = #{device_password}




		, LOCKER_IDX = #{locker_idx}




		, return_plan_date = TO_DATE(#{return_plan_date}, 'yyyy-MM-dd HH24:mi:ss')



	,CANCEL_DATE = SYSDATE
	,CANCEL_ID = #{cancel_id}
	,CANCEL_IP = #{cancel_ip}
	,CANCEL_YN = #{cancel_yn}
	,CANCEL_REASON = #{cancel_reason}


	,return_device_code = #{return_device_code}

WHERE
	1=1


		AND	RESERVE_IDX = #{reserve_idx}
		AND DEVICE_CODE = #{device_code}


		AND	RESERVE_BUNDLE_IDX = #{reserve_bundle_idx}
		AND DEVICE_CODE = #{device_code}


		AND PK = #{pk}
		AND RESERVE_STATUS = '1'

UPDATE NEIGHBORHOOD_LIBRARY_RESERVE SET SMS_SEND_YN = #{sms_send_yn}, SMS_SEND_DATE = SYSDATE WHERE 1=1
AND RESERVE_IDX = #{reserve_idx}
AND RESERVE_BUNDLE_IDX = #{reserve_bundle_idx}

UPDATE
	NEIGHBORHOOD_LIBRARY_RESERVE
SET
	LOCKER_IDX = #{locker_each_idx}
WHERE
1=1


 	AND RESERVE_BUNDLE_IDX = #{reserve_bundle_idx}


 	AND RESERVE_IDX = #{reserve_idx}


 AND DEVICE_IDX = #{device_idx}
 AND DEVICE_CODE = #{device_code}
 AND RESERVE_STATUS = '2'

mapper.select:
SELECT
	HOMEPAGE_ID, RESERVE_STATUS, DEVICE_IDX, DEVICE_CODE, RESERVE_IDX, 
	RESERVE_BUNDLE_IDX, LOCKER_IDX, DEVICE_PASSWORD, DEVICE_NAME, MEMBER_ID,			
	USER_KEY, MEMBER_NAME, LEND_DATE, MANAGE_CODE, LIB_NAME, 
	BOOK_KEY, REG_NO, BOOK_ISBN, BOOK_NAME, ADD_DATE, 
	ADD_ID, ADD_IP, CANCEL_YN, CANCEL_DATE, CANCEL_REASON, 
	CANCEL_ID, CANCEL_IP, SMS_SEND_YN, SMS_SEND_DATE, HOMEPAGE_SEND_TELL, 
	APPLICANT_CELL_PHONE, EXPIRE_DATE_CNT, PK, LARGE_BOOK_YN, USER_NO, 
	TAKE_TERM, RESERVE_END_DATE, RESERVE_START_DATE, RETURN_DEVICE_CODE, EXPIRE_DATE,
	CALL_NO
FROM
	NEIGHBORHOOD_LIBRARY_RESERVE
WHERE
	LOCKER_IDX = #{locker_idx}
AND DEVICE_PASSWORD = #{device_password}
AND DEVICE_IDX = #{device_idx}
AND RESERVE_STATUS = '3'
AND RESERVE_IDX = (SELECT MAX(RESERVE_IDX) 
					FROM NEIGHBORHOOD_LIBRARY_RESERVE 
					WHERE LOCKER_IDX = #{locker_idx}
					AND DEVICE_PASSWORD = #{device_password}
					AND DEVICE_IDX = #{device_idx}
					AND RESERVE_STATUS = '3');

